// usage: node shot.js out.png [--w 1440] [--h 900] [--dpr 1] [--wait 1500] [--reduced] [--clip x,y,w,h] [--mouse "x,y;x,y;..."] [--click x,y] [--url file] [--fps]
const puppeteer = require('puppeteer-core');
const args = process.argv.slice(2);
const out = args[0];
const opt = (k, d) => { const i = args.indexOf('--' + k); return i >= 0 ? args[i + 1] : d; };
const flag = k => args.includes('--' + k);
(async () => {
  const W = +opt('w', 1440), H = +opt('h', 900), dpr = +opt('dpr', 1), wait = +opt('wait', 1500);
  const browser = await puppeteer.launch({ executablePath: '/usr/bin/chromium', headless: 'new',
    args: ['--no-sandbox', '--disable-gpu', '--hide-scrollbars', '--force-color-profile=srgb', '--window-size=' + W + ',' + H] });
  const page = await browser.newPage();
  const errs = [];
  page.on('console', m => { if (m.type() === 'error' || m.type() === 'warning' || flag('log')) errs.push('[' + m.type() + '] ' + m.text()); });
  page.on('pageerror', e => errs.push('[pageerror] ' + (e.stack || e.message)));
  await page.setViewport({ width: W, height: H, deviceScaleFactor: dpr, hasTouch: flag('touch') });
  if (flag('reduced')) await page.emulateMediaFeatures([{ name: 'prefers-reduced-motion', value: 'reduce' }]);
  const t0 = Date.now();
  await page.goto(opt('url', 'file:///app/index.html'), { waitUntil: 'load' });
  const tLoad = Date.now() - t0;
  const mouse = opt('mouse', '');
  if (mouse) {
    const pts = mouse.split(';').map(p => p.split(',').map(Number));
    await new Promise(r => setTimeout(r, Math.min(wait, 400)));
    for (let i = 0; i < pts.length; i++) {
      await page.mouse.move(pts[i][0], pts[i][1], { steps: 12 });
      await new Promise(r => setTimeout(r, 60));
    }
  }
  const click = opt('click', '');
  if (click) { const [x, y] = click.split(',').map(Number); await page.mouse.click(x, y); }
  await new Promise(r => setTimeout(r, wait));
  if (flag('fps')) {
    const fps = await page.evaluate(() => new Promise(res => { let n = 0; const t0 = performance.now(); const times = []; let last = t0; function f(t) { n++; times.push(t - last); last = t; if (t - t0 < 2000) requestAnimationFrame(f); else res({ fps: n / ((t - t0) / 1000), maxGap: Math.max(...times.slice(1)) }); } requestAnimationFrame(f); }));
    console.log('fps', JSON.stringify(fps));
  }
  const clip = opt('clip', '');
  const o = { path: out };
  if (clip) { const [x, y, w, h] = clip.split(',').map(Number); o.clip = { x, y, width: w, height: h }; }
  await page.screenshot(o);
  console.log('load ms', tLoad, errs.length ? '\nERRORS:\n' + errs.join('\n') : '(no console errors)');
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });
EOF
