(function () {
'use strict';

/* ==========================================================================
   A steaming bowl of vegan ramen.
   Everything on screen is painted at runtime with Canvas 2D — no images,
   no fonts, no libraries, no network. The static parts of the picture are
   painted once per size into off-screen layers; each frame then composes
   those layers with the living parts: steam (a small fluid simulation),
   the broth surface, drifting oil and garnish, and light that follows the
   pointer.
   ========================================================================== */

const canvas = document.getElementById('scene');
const ctx = canvas.getContext('2d', { alpha: false });

/* ---------- small helpers ---------- */
const PI = Math.PI, TAU = PI * 2;
const min = Math.min, max = Math.max, abs = Math.abs, sqrt = Math.sqrt, pow = Math.pow, exp = Math.exp;
const sin = Math.sin, cos = Math.cos, atan2 = Math.atan2, hypot = Math.hypot, floor = Math.floor, ceil = Math.ceil, round = Math.round;
const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
const lerp = (a, b, t) => a + (b - a) * t;
const sstep = (a, b, v) => { const t = clamp((v - a) / (b - a), 0, 1); return t * t * (3 - 2 * t); };
const now = () => performance.now();

/* deterministic random numbers, so the dish is plated the same way every time */
function rng(seed) {
  let s = seed | 0;
  return function () {
    s = (s + 0x6D2B79F5) | 0;
    let t = Math.imul(s ^ (s >>> 15), 1 | s);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/* value noise + fbm */
const NP = new Uint8Array(512), NV = new Float32Array(256);
(function () {
  const r = rng(90210), p = [];
  for (let i = 0; i < 256; i++) { p[i] = i; NV[i] = r(); }
  for (let i = 255; i > 0; i--) { const j = floor(r() * (i + 1)), t = p[i]; p[i] = p[j]; p[j] = t; }
  for (let i = 0; i < 512; i++) NP[i] = p[i & 255];
})();
function noise2(x, y) {
  const xi = floor(x), yi = floor(y), xf = x - xi, yf = y - yi;
  const u = xf * xf * (3 - 2 * xf), v = yf * yf * (3 - 2 * yf);
  const X = xi & 255, Y = yi & 255;
  const a = NP[X] + Y, b = NP[X + 1] + Y;
  const v00 = NV[NP[a]], v10 = NV[NP[b]], v01 = NV[NP[a + 1]], v11 = NV[NP[b + 1]];
  return v00 + (v10 - v00) * u + (v01 - v00 + (v00 - v10 - v01 + v11) * u) * v;
}
function fbm(x, y, oct) {
  let a = 0.5, f = 0, n = 0;
  for (let i = 0; i < oct; i++) { f += a * noise2(x, y); n += a; a *= 0.5; x = x * 2.03 + 17.13; y = y * 2.03 + 9.71; }
  return f / n;
}

function mk(w, h) {
  const c = document.createElement('canvas');
  c.width = max(1, ceil(w)); c.height = max(1, ceil(h));
  return c;
}
const rgba = (r, g, b, a) => 'rgba(' + (r | 0) + ',' + (g | 0) + ',' + (b | 0) + ',' + a + ')';
/* linear-light colour → css (keeps the hand-tuned shading maths honest) */
const to8 = v => round(255 * pow(clamp(v, 0, 1), 1 / 2.2));
const lin = (r, g, b) => 'rgb(' + to8(r) + ',' + to8(g) + ',' + to8(b) + ')';
const norm3 = (x, y, z) => { const l = 1 / hypot(x, y, z); return [x * l, y * l, z * l]; };

/* ---------- view / layout ---------- */
/* All painting happens in "bowl units": 1 unit = the outer radius of the rim.
   view.K converts units to device pixels, (view.ox, view.oy) is the centre
   of the rim on the canvas. */
const quality = { maxDpr: 2, maxPixels: 8.4e6, steam: 1 };
const view = { W: 1, H: 1, dpr: 1, S: 100, K: 100, ox: 0, oy: 0 };

function measure() {
  const W = max(1, window.innerWidth || document.documentElement.clientWidth || 1);
  const H = max(1, window.innerHeight || document.documentElement.clientHeight || 1);
  let dpr = clamp(window.devicePixelRatio || 1, 1, quality.maxDpr);
  if (W * H * dpr * dpr > quality.maxPixels) dpr = sqrt(quality.maxPixels / (W * H));
  view.W = W; view.H = H; view.dpr = dpr;
  view.S = max(24, min(W * 0.36, H * 0.285));
  view.K = view.S * dpr;
  view.ox = round((W * 0.5 - view.S * 0.07) * dpr);
  view.oy = round(H * (W >= H ? 0.615 : 0.575) * dpr);
}

/* ---------- camera & bowl geometry (units of R; y up, z toward the viewer) ---------- */
const SQ = 0.6, CQ = 0.8;                 // sin / cos of the camera's elevation
const RIM_C = 0.976, RIM_T = 0.024;       // lip: centre-line radius and tube radius
const RIM_IN = RIM_C - RIM_T;
const BODY_H = 0.74, FOOT_R = 0.40, WALL = 0.048;
const BROTH_D = 0.13;                     // how far below the lip the broth sits
function rOut(h) { const t = clamp(h / BODY_H, 0, 1); return FOOT_R + (1 - FOOT_R) * pow(1 - pow(t, 1.9), 0.72); }
function rIn(h) { return rOut(h) - WALL; }
const RB = rIn(BROTH_D), YB = BROTH_D * CQ;        // broth radius, and its screen offset below the rim centre
const TABLE_Y = (BODY_H + 0.05) * CQ;              // screen offset of the table point under the bowl

/* project a point on / above the broth surface to bowl-unit screen coords */
const sx = (x) => x;
const sy = (z, y) => YB + z * SQ - (y || 0) * CQ;

/* lighting set-up shared by the painters */
const L_KEY = norm3(-0.52, 0.66, -0.54);          // warm lamp: above, behind, to the left
const L_FILL = norm3(-0.62, 0.38, 0.69);          // dim room glow from the front-left
const VIEW = [0, SQ, CQ];
const H_FILL = norm3(L_FILL[0] + VIEW[0], L_FILL[1] + VIEW[1], L_FILL[2] + VIEW[2]);
const H_KEY = norm3(L_KEY[0] + VIEW[0], L_KEY[1] + VIEW[1], L_KEY[2] + VIEW[2]);

/* soft blob: radial falloff painted as a (possibly squashed) gradient */
function blob(g, x, y, rx, ry, c0, c1, mid) {
  g.save();
  g.translate(x, y); g.scale(1, ry / rx);
  const gr = g.createRadialGradient(0, 0, 0, 0, 0, rx);
  gr.addColorStop(0, c0);
  if (mid) gr.addColorStop(mid[0], mid[1]);
  gr.addColorStop(1, c1);
  g.fillStyle = gr;
  g.beginPath(); g.arc(0, 0, rx, 0, TAU); g.fill();
  g.restore();
}

/* ==========================================================================
   Background: a dark wooden counter that only exists where the lamp reaches.
   ========================================================================== */
function buildBackground() {
  const w = canvas.width, h = canvas.height, K = view.K, ox = view.ox, oy = view.oy;
  const cv = mk(w, h), g = cv.getContext('2d', { alpha: false });
  const R = rng(4242);
  const ty = oy + TABLE_Y * K;                      // table point under the bowl

  let gr = g.createLinearGradient(0, 0, 0, h);
  gr.addColorStop(0, '#040302'); gr.addColorStop(0.6, '#070504'); gr.addColorStop(1, '#060403');
  g.fillStyle = gr; g.fillRect(0, 0, w, h);

  /* --- the counter top, painted on its own canvas then masked by the pool of light --- */
  const tv = mk(w, h), tg = tv.getContext('2d');
  tg.fillStyle = '#34190c'; tg.fillRect(0, 0, w, h);
  const plank = 0.86 * SQ * K;                      // board width in device px (foreshortened)
  const y0 = ty - ceil((ty + plank) / plank) * plank + plank * 0.37;
  for (let py = y0; py < h + plank; py += plank) {
    /* each board has its own tone */
    const tone = R();
    tg.fillStyle = tone < 0.5 ? rgba(0, 0, 0, 0.10 + 0.22 * R()) : rgba(150, 84, 40, 0.04 + 0.08 * R());
    tg.fillRect(0, py, w, plank);
    /* grain: long, slightly wandering streaks */
    const n = 46;
    for (let i = 0; i < n; i++) {
      const yy = py + R() * plank, x0 = (R() * 1.3 - 0.3) * w, len = (0.15 + R() * R() * 1.1) * w;
      const amp = (0.6 + R() * 2.2) * view.dpr, f = 0.6 + R() * 1.4, ph = R() * 100;
      const dark = R() < 0.62;
      tg.strokeStyle = dark ? rgba(8, 3, 1, 0.10 + 0.28 * R()) : rgba(190, 112, 58, 0.03 + 0.09 * R());
      tg.lineWidth = (0.5 + R() * 1.4) * view.dpr;
      tg.beginPath();
      const steps = max(6, ceil(len / (22 * view.dpr)));
      for (let s = 0; s <= steps; s++) {
        const x = x0 + len * s / steps;
        const y = yy + (noise2(x / K * f * 1.7 + ph, ph * 0.37) - 0.5) * 2 * amp;
        if (s) tg.lineTo(x, y); else tg.moveTo(x, y);
      }
      tg.stroke();
    }
    /* seam between boards */
    tg.fillStyle = 'rgba(0,0,0,0.6)'; tg.fillRect(0, py - view.dpr, w, max(1, 1.6 * view.dpr));
    tg.fillStyle = 'rgba(255,190,130,0.05)'; tg.fillRect(0, py + 0.8 * view.dpr, w, max(1, view.dpr));
  }
  /* a few board ends */
  for (let i = 0; i < 7; i++) {
    const row = floor(R() * ceil(h / plank + 1)), px = R() * w;
    const py = y0 + row * plank;
    tg.fillStyle = 'rgba(0,0,0,0.55)'; tg.fillRect(px, py, max(1, 1.4 * view.dpr), plank);
  }
  /* broad lacquer sheen: the counter is glossy, so it keeps a soft echo of the lamp */
  tg.globalCompositeOperation = 'lighter';
  tg.save();
  tg.translate(ox - 0.55 * K, ty - 0.62 * K); tg.scale(1, 0.34);
  gr = tg.createRadialGradient(0, 0, 0, 0, 0, 2.3 * K);
  gr.addColorStop(0, 'rgba(255,170,96,0.20)'); gr.addColorStop(0.4, 'rgba(255,150,80,0.07)'); gr.addColorStop(1, 'rgba(255,140,70,0)');
  tg.fillStyle = gr; tg.beginPath(); tg.arc(0, 0, 2.3 * K, 0, TAU); tg.fill();
  tg.restore();

  /* mask: pool of lamplight, an ellipse lying on the table */
  tg.globalCompositeOperation = 'destination-in';
  tg.save();
  tg.translate(ox - 0.22 * K, ty - 0.10 * K); tg.scale(1, 0.62);
  const pr = 3.5 * K;
  gr = tg.createRadialGradient(0, 0, 0, 0, 0, pr);
  gr.addColorStop(0, 'rgba(0,0,0,1)'); gr.addColorStop(0.22, 'rgba(0,0,0,0.80)');
  gr.addColorStop(0.45, 'rgba(0,0,0,0.42)'); gr.addColorStop(0.7, 'rgba(0,0,0,0.14)'); gr.addColorStop(1, 'rgba(0,0,0,0)');
  tg.fillStyle = gr; tg.fillRect(-w * 2, -h * 4, w * 4, h * 8);
  tg.restore();
  tg.globalCompositeOperation = 'source-over';
  g.drawImage(tv, 0, 0);

  /* --- contact shadow: the bowl sits heavily on the wood --- */
  g.save();
  g.translate(ox + 0.03 * K, ty + 0.02 * K); g.scale(1, SQ);
  gr = g.createRadialGradient(0, 0, 0.30 * K, 0, 0, 1.22 * K);
  gr.addColorStop(0, 'rgba(0,0,0,0.92)'); gr.addColorStop(0.45, 'rgba(0,0,0,0.62)'); gr.addColorStop(0.75, 'rgba(0,0,0,0.2)'); gr.addColorStop(1, 'rgba(0,0,0,0)');
  g.fillStyle = gr; g.beginPath(); g.arc(0, 0, 1.25 * K, 0, TAU); g.fill();
  g.restore();

  /* --- warm haze hanging in the air where the lamp is --- */
  g.globalCompositeOperation = 'lighter';
  gr = g.createRadialGradient(ox - 0.9 * K, oy - 2.2 * K, 0, ox - 0.9 * K, oy - 2.2 * K, 3.4 * K);
  gr.addColorStop(0, 'rgba(110,52,20,0.16)'); gr.addColorStop(0.5, 'rgba(70,30,12,0.06)'); gr.addColorStop(1, 'rgba(0,0,0,0)');
  g.fillStyle = gr; g.fillRect(0, 0, w, h);
  g.globalCompositeOperation = 'source-over';

  /* --- vignette --- */
  const vr = hypot(w, h) * 0.62;
  gr = g.createRadialGradient(ox, oy - 0.2 * K, vr * 0.35, ox, oy - 0.2 * K, vr);
  gr.addColorStop(0, 'rgba(0,0,0,0)'); gr.addColorStop(0.7, 'rgba(0,0,0,0.45)'); gr.addColorStop(1, 'rgba(0,0,0,0.85)');
  g.fillStyle = gr; g.fillRect(0, 0, w, h);

  /* --- a whisper of grain so the dark gradients never band --- */
  const nt = mk(128, 128), ng = nt.getContext('2d'), id = ng.createImageData(128, 128);
  for (let i = 0; i < id.data.length; i += 4) {
    const v = R() * R() * 7;
    id.data[i] = v * 1.15; id.data[i + 1] = v; id.data[i + 2] = v * 0.85; id.data[i + 3] = 255;
  }
  ng.putImageData(id, 0, 0);
  g.globalCompositeOperation = 'lighter';
  g.fillStyle = g.createPattern(nt, 'repeat');
  g.fillRect(0, 0, w, h);
  g.globalCompositeOperation = 'source-over';
  return cv;
}

/* ==========================================================================
   The bowl: dark stoneware, shaded as a real surface of revolution.
   ========================================================================== */

/* outline of the outside of the bowl as seen by the camera */
function bowlSilhouette() {
  const p = new Path2D(), N = 180, HS = 140, ys = [];
  for (let i = 0; i <= N; i++) {
    const x = -1 + 2 * i / N; let ym = 0;
    for (let j = 0; j <= HS; j++) {
      const h = BODY_H * j / HS, r = rOut(h);
      if (r > abs(x)) { const y = h * CQ + SQ * sqrt(r * r - x * x); if (y > ym) ym = y; }
    }
    ys.push(ym);
  }
  p.moveTo(-1, 0);
  p.ellipse(0, 0, 1, SQ, 0, PI, TAU);
  for (let i = N; i >= 0; i--) p.lineTo(-1 + 2 * i / N, ys[i]);
  p.closePath();
  return p;
}

function shadeExt(h, cp, sp) {
  const e = 0.003, dr = (rOut(h + e) - rOut(h - e)) / (2 * e);
  let nr = 1, ny = dr; const il = 1 / hypot(nr, ny); nr *= il; ny *= il;
  const nx = nr * cp, nz = nr * sp;
  const nv = max(0, ny * VIEW[1] + nz * VIEW[2]);
  const kd = max(0, nx * L_KEY[0] + ny * L_KEY[1] + nz * L_KEY[2]);
  const fd = max(0, nx * L_FILL[0] + ny * L_FILL[1] + nz * L_FILL[2]);
  const fs = pow(max(0, nx * H_FILL[0] + ny * H_FILL[1] + nz * H_FILL[2]), 30);
  const fres = pow(1 - nv, 4);
  /* the glaze mirrors the lamplit counter on its underside */
  const ry = 2 * nv * ny - VIEW[1];
  const tab = sstep(0.05, -0.65, ry) * (0.22 + 0.78 * fres) * (0.55 + 0.45 * (0.5 - 0.5 * cp));
  const hk = h / BODY_H;
  /* dark teal-black body; iron-rust where the glaze runs thin under the lip */
  const rust = 1 - sstep(0.0, 0.06, h);
  const ar = lerp(0.020, 0.105, rust), ag = lerp(0.030, 0.048, rust), ab = lerp(0.038, 0.022, rust);
  const Er = 0.20 + kd * 1.5 + fd * 0.70, Eg = 0.17 + kd * 1.2 + fd * 0.52, Eb = 0.15 + kd * 0.85 + fd * 0.36;
  const ao = 1 - 0.8 * sstep(0.5, 1.0, hk);
  return lin((ar * Er + fs * 0.11 + fres * 0.030 + tab * 0.075) * ao,
             (ag * Eg + fs * 0.085 + fres * 0.020 + tab * 0.032) * ao,
             (ab * Eb + fs * 0.06 + fres * 0.014 + tab * 0.013) * ao);
}

function shadeInt(h, cp, sp) {            // back half of the inside wall (sp <= 0)
  const e = 0.003, dr = (rOut(h + e) - rOut(h - e)) / (2 * e);
  let nr = -1, ny = -dr; const il = 1 / hypot(nr, ny); nr *= il; ny *= il;
  const nx = nr * cp, nz = nr * sp;
  const kd = max(0, nx * L_KEY[0] + ny * L_KEY[1] + nz * L_KEY[2]);
  const nv = max(0, ny * VIEW[1] + nz * VIEW[2]);
  const fres = pow(1 - nv, 3);
  const glow = exp(-(BROTH_D - h) / 0.055);          // the broth lights the wall from below
  const lip = 0.45 + 0.55 * sstep(0.0, 0.035, h);     // shade tucked under the lip
  const Er = (0.14 + kd * 1.9) * lip, Eg = (0.12 + kd * 1.5) * lip, Eb = (0.11 + kd * 1.05) * lip;
  return lin(0.034 * Er + glow * 0.150 + fres * 0.010,
             0.036 * Eg + glow * 0.048 + fres * 0.008,
             0.040 * Eb + glow * 0.010 + fres * 0.006);
}

/* the broth: creamy sesame-miso, marbled, with chili oil gathering toward the edge */
function buildBrothTexture() {
  const N = 300, cv = mk(N, N), g = cv.getContext('2d'), id = g.createImageData(N, N), d = id.data;
  for (let j = 0; j < N; j++) {
    for (let i = 0; i < N; i++) {
      const u = (i + 0.5) / N * 2 - 1, v = (j + 0.5) / N * 2 - 1, r = hypot(u, v);
      const k = (j * N + i) * 4;
      if (r > 1.03) { d[k + 3] = 0; continue; }
      const sw = 1.5 * (1 - r) * (1 - r), cs = cos(sw), sn = sin(sw);
      const x = u * cs - v * sn, y = u * sn + v * cs;
      const w1 = fbm(x * 2.1 + 3.1, y * 2.1 + 7.7, 3), w2 = fbm(x * 2.1 + 11.3, y * 2.1 + 1.9, 3);
      const n = fbm(x * 2.8 + 2.6 * w1, y * 2.8 + 2.6 * w2, 4);
      const o = fbm(x * 4.2 + 20 + 1.7 * w2, y * 4.2 + 40 + 1.7 * w1, 3);
      const cream = sstep(0.40, 0.70, n);
