    for (let i = 0; i < N; i++) {
      const a0 = TAU * i / N, a1 = TAU * (i + 1.4) / N, a = (a0 + a1) / 2;
      const toward = 0.5 + 0.5 * cos(a - az);            // 1 on the lamp side of the rim
