function genNoodles() {
  const R = rng(271828), strands = [];
  const N = 54, NX = 0.02, NZ = 0.05;
  for (let i = 0; i < N; i++) {
    const f = i / (N - 1);
    const rad0 = 0.07 + 0.56 * pow(f, 0.9) + (R() - 0.5) * 0.05;
    const a0 = R() * TAU, span = 1.1 + R() * 2.3;
