        g.strokeStyle = rgba(lerp(206, 216, warm), lerp(146, 160, warm), lerp(60, 76, warm), 1); g.lineWidth = w; strokeRun(g, p, i, j, 0, 0);
        g.strokeStyle = rgba(lerp(236, 242, warm), lerp(192, 204, warm), lerp(108, 126, warm), 1); g.lineWidth = w * 0.74; strokeRun(g, p, i, j, -0.001, -0.0035);
        g.strokeStyle = rgba(250, lerp(226, 234, warm), lerp(160, 178, warm), 1); g.lineWidth = w * 0.40; strokeRun(g, p, i, j, -0.002, -0.0065);
