/* ==========================================================================
   Toppings. Each is painted once into its own sprite (so it can bob on the
   broth) using the same camera as the bowl.
   ========================================================================== */
const P = (x, z, y) => [x, YB + z * SQ - (y || 0) * CQ];

function polyPath(g, pts) {
  g.beginPath(); g.moveTo(pts[0][0], pts[0][1]);
  for (let i = 1; i < pts.length; i++) g.lineTo(pts[i][0], pts[i][1]);
  g.closePath();
}
/* paint inside a parallelogram using unit-square coordinates */
function inFace(g, o, u, v, fn) {
  g.save();
  g.transform(u[0] - o[0], u[1] - o[1], v[0] - o[0], v[1] - o[1], o[0], o[1]);
  fn(g);
  g.restore();
}
/* shadow / occlusion a topping presses into the broth */
function brothShadow(g, x, z, rx, rz, a) {
  const p = P(x, z, 0);
  blob(g, p[0] + 0.012, p[1] + 0.014, rx, rz * SQ, rgba(44, 12, 0, a), 'rgba(44,12,0,0)', [0.55, rgba(44, 12, 0, a * 0.6)]);
}

/* ---------- seared tofu ---------- */
function paintTofu(g, cx, cz, yaw, w, d, h, y0, seed) {
  const R = rng(seed), ca = cos(yaw), sa = sin(yaw), hw = w / 2, hd = d / 2;
  const loc = (lx, ly, lz) => P(cx + lx * ca - lz * sa, cz + lx * sa + lz * ca, max(0, y0 + ly));
  const cs = [[-hw, -hd], [hw, -hd], [hw, hd], [-hw, hd]];
  const top = cs.map(c => loc(c[0], h, c[1])), bot = cs.map(c => loc(c[0], 0, c[1]));
  if (y0 < 0.02) brothShadow(g, cx, cz, w * 0.9, d * 1.0, 0.6);

  /* sides */
  for (let i = 0; i < 4; i++) {
    const j = (i + 1) % 4;
    const mx = (cs[i][0] + cs[j][0]) / 2, mz = (cs[i][1] + cs[j][1]) / 2;
    let nx = mx * ca - mz * sa, nz = mx * sa + mz * ca; const nl = hypot(nx, nz); nx /= nl; nz /= nl;
    if (nz <= 0.02) continue;
    const lit = clamp(0.5 + 0.55 * (nx * -0.55 + nz * 0.45), 0, 1);
    polyPath(g, [top[i], top[j], bot[j], bot[i]]);
    g.save(); g.clip();
    inFace(g, top[i], top[j], bot[i], f => {
      const gr = f.createLinearGradient(0, 0, 0, 1);
      gr.addColorStop(0, '#c98a3a'); gr.addColorStop(0.07, '#e2b874'); gr.addColorStop(0.2, '#f6ead0');
      gr.addColorStop(0.62, '#efdcb6'); gr.addColorStop(0.88, '#e0b47a'); gr.addColorStop(1, '#bf7430');
      f.fillStyle = gr; f.fillRect(-0.02, -0.02, 1.04, 1.04);
      /* turn of the form */
      f.fillStyle = rgba(70, 30, 6, (1 - lit) * 0.42); f.fillRect(-0.02, -0.02, 1.04, 1.04);
      /* the little pores of pressed tofu */
      for (let k = 0; k < 26; k++) {
        f.fillStyle = rgba(170, 130, 80, 0.10 + 0.22 * R());
        f.beginPath(); f.ellipse(R(), 0.16 + R() * 0.7, 0.008 + R() * 0.016, 0.014 + R() * 0.03, 0, 0, TAU); f.fill();
      }
      /* golden crust creeping in from the vertical corners */
      let eg = f.createLinearGradient(0, 0, 0.12, 0);
      eg.addColorStop(0, 'rgba(196,128,50,0.55)'); eg.addColorStop(1, 'rgba(196,128,50,0)');
      f.fillStyle = eg; f.fillRect(0, 0, 0.12, 1);
      eg = f.createLinearGradient(1, 0, 0.88, 0);
      eg.addColorStop(0, 'rgba(196,128,50,0.55)'); eg.addColorStop(1, 'rgba(196,128,50,0)');
      f.fillStyle = eg; f.fillRect(0.88, 0, 0.12, 1);
    });
    g.restore();
  }
  /* seared top */
  polyPath(g, top);
  g.save(); g.clip();
  inFace(g, top[0], top[1], top[3], f => {
    let gr = f.createLinearGradient(0, 0, 1, 1);
    gr.addColorStop(0, '#f0c478'); gr.addColorStop(0.5, '#e2a550'); gr.addColorStop(1, '#cf8a36');
    f.fillStyle = gr; f.fillRect(-0.02, -0.02, 1.04, 1.04);
    for (let k = 0; k < 9; k++) {
      const bx = R(), by = R(), br = 0.12 + R() * 0.22;
      const bg = f.createRadialGradient(bx, by, 0, bx, by, br);
      bg.addColorStop(0, rgba(150, 78, 22, 0.20 + 0.25 * R())); bg.addColorStop(1, 'rgba(150,78,22,0)');
      f.fillStyle = bg; f.fillRect(0, 0, 1, 1);
    }
    /* char lines from the grill */
    const ga = 0.5 + R() * 0.3;
    for (let k = 0; k < 3; k++) {
      const c0 = 0.2 + k * 0.3 + (R() - 0.5) * 0.05;
      for (let q = 0; q < 3; q++) {
        const hw2 = 0.055 - q * 0.016;
        f.fillStyle = rgba(92, 40, 10, 0.22 + q * 0.10);
        f.beginPath(); f.moveTo(c0 - hw2 - ga * 0.5, 1.05); f.lineTo(c0 + hw2 - ga * 0.5, 1.05);
        f.lineTo(c0 + hw2 + ga * 0.5, -0.05); f.lineTo(c0 - hw2 + ga * 0.5, -0.05); f.closePath(); f.fill();
      }
    }
    /* darker, crisper rim */
    for (let e = 0; e < 4; e++) {
      const eg = e === 0 ? f.createLinearGradient(0, 0, 0.14, 0) : e === 1 ? f.createLinearGradient(1, 0, 0.86, 0)
        : e === 2 ? f.createLinearGradient(0, 0, 0, 0.14) : f.createLinearGradient(0, 1, 0, 0.86);
      eg.addColorStop(0, 'rgba(120,58,14,0.50)'); eg.addColorStop(1, 'rgba(120,58,14,0)');
      f.fillStyle = eg; f.fillRect(0, 0, 1, 1);
    }
    /* wet sheen */
    gr = f.createRadialGradient(0.3, 0.3, 0, 0.3, 0.3, 0.55);
    gr.addColorStop(0, 'rgba(255,240,200,0.42)'); gr.addColorStop(1, 'rgba(255,240,200,0)');
    f.fillStyle = gr; f.fillRect(0, 0, 1, 1);
  });
  g.restore();
  /* bevel highlights along the top edges, and soft separation where faces meet */
  g.lineCap = 'round';
  for (let i = 0; i < 4; i++) {
    const j = (i + 1) % 4;
    const mz = ((cs[i][0] + cs[j][0]) / 2) * sa + ((cs[i][1] + cs[j][1]) / 2) * ca;
    g.strokeStyle = mz > 0 ? 'rgba(255,238,196,0.75)' : 'rgba(255,226,170,0.40)';
    g.lineWidth = mz > 0 ? 0.0055 : 0.004;
    g.beginPath(); g.moveTo(top[i][0], top[i][1]); g.lineTo(top[j][0], top[j][1]); g.stroke();
  }
  /* the vertical corner nearest the viewer */
  let ni = 0; for (let i = 1; i < 4; i++) if (top[i][1] > top[ni][1]) ni = i;
  g.strokeStyle = 'rgba(255,244,214,0.5)'; g.lineWidth = 0.004;
  g.beginPath(); g.moveTo(top[ni][0], top[ni][1] + 0.004); g.lineTo(bot[ni][0], bot[ni][1] - 0.006); g.stroke();
  /* a few sesame seeds resting on the crust */
  for (let k = 0; k < 4; k++) {
    const u = 0.2 + R() * 0.6, v = 0.2 + R() * 0.6;
    const x = top[0][0] + (top[1][0] - top[0][0]) * u + (top[3][0] - top[0][0]) * v;
    const y = top[0][1] + (top[1][1] - top[0][1]) * u + (top[3][1] - top[0][1]) * v;
    paintSeed(g, x, y, R() * PI, R() < 0.25);
  }
}

function paintSeed(g, x, y, rot, black) {
  g.save(); g.translate(x, y); g.rotate(rot); g.scale(1, 0.62);
  g.fillStyle = 'rgba(60,24,4,0.45)'; g.beginPath(); g.ellipse(0.0015, 0.004, 0.0105, 0.0058, 0, 0, TAU); g.fill();
  g.fillStyle = black ? '#1c1410' : '#f1dfae';
  g.beginPath(); g.moveTo(-0.0105, 0); g.quadraticCurveTo(-0.002, -0.0075, 0.0105, 0); g.quadraticCurveTo(-0.002, 0.0075, -0.0105, 0); g.fill();
  g.fillStyle = black ? 'rgba(160,150,140,0.5)' : 'rgba(255,255,244,0.8)';
  g.beginPath(); g.ellipse(-0.001, -0.0018, 0.0045, 0.0014, 0, 0, TAU); g.fill();
  g.restore();
}

/* ---------- shiitake with a star cut ---------- */
function paintShiitake(g, cx, cz, r, hh, seed, y0) {
  const R = rng(seed), c = P(cx, cz, y0 || 0), x = c[0], yb = c[1];
  const ryb = r * SQ, ryt = sqrt(ryb * ryb + hh * CQ * hh * CQ);
  brothShadow(g, cx, cz, r * 1.28, r * 1.28, 0.62);
  const cap = new Path2D();
  cap.ellipse(x, yb, r, ryt, 0, PI, TAU); cap.ellipse(x, yb, r, ryb, 0, 0, PI); cap.closePath();
  g.save(); g.clip(cap);
  let gr = g.createRadialGradient(x - r * 0.32, yb - ryt * 0.62, 0, x - r * 0.1, yb - ryt * 0.2, r * 1.5);
  gr.addColorStop(0, '#a56c3e'); gr.addColorStop(0.3, '#7d4a26'); gr.addColorStop(0.68, '#4f2a14'); gr.addColorStop(1, '#27120a');
  g.fillStyle = gr; g.fillRect(x - r - 0.01, yb - ryt - 0.01, 2 * r + 0.02, ryt + ryb + 0.02);
  /* fibrous, slightly cracked skin */
  const ax = x, ay = yb - hh * CQ;
  for (let k = 0; k < 70; k++) {
    const a = R() * TAU, r0 = 0.25 + R() * 0.45, r1 = r0 + 0.12 + R() * 0.35;
    const pt = t => [x + cos(a) * r * t, yb + sin(a) * r * t * SQ - hh * CQ * sqrt(max(0, 1 - t * t))];
    const p0 = pt(r0), p1 = pt(min(1, r1));
    g.strokeStyle = R() < 0.55 ? rgba(30, 12, 4, 0.10 + 0.14 * R()) : rgba(200, 140, 90, 0.05 + 0.09 * R());
    g.lineWidth = 0.002 + R() * 0.004;
    g.beginPath(); g.moveTo(p0[0], p0[1]); g.lineTo(p1[0], p1[1]); g.stroke();
  }
  /* shade rolling under the edge */
  gr = g.createLinearGradient(0, yb - ryb * 0.2, 0, yb + ryb);
  gr.addColorStop(0, 'rgba(18,6,2,0)'); gr.addColorStop(1, 'rgba(18,6,2,0.72)');
  g.fillStyle = gr; g.fillRect(x - r, yb - ryb * 0.2, 2 * r, ryb * 1.3);
  /* warm bounce from the broth along the lower rim */
  g.strokeStyle = 'rgba(255,140,50,0.22)'; g.lineWidth = 0.012;
  g.beginPath(); g.ellipse(x, yb - 0.004, r, ryb, 0, 0.25, PI - 0.25); g.stroke();

  /* star cut (kazari-giri): three tapered grooves crossing at the crown */
  const dome = (al, be) => [x + r * sin(al) * cos(be), yb + r * sin(al) * sin(be) * SQ - hh * cos(al) * CQ];
  const b0 = R() * PI;
  for (let k = 0; k < 3; k++) {
    const be = b0 + k * PI / 3 + (R() - 0.5) * 0.12, a0 = 0.86 + R() * 0.1, M = 14, L = [], Rr = [];
    for (let i = 0; i <= M; i++) {
      const al = -a0 + 2 * a0 * i / M, p = dome(al, be), q = dome(al + 0.02, be);
      let tx = q[0] - p[0], ty = q[1] - p[1]; const il = 1 / (hypot(tx, ty) || 1); tx *= il; ty *= il;
      const wd = r * 0.085 * pow(max(0, 1 - pow(al / a0, 2)), 0.75);
      L.push([p[0] - ty * wd, p[1] + tx * wd]); Rr.push([p[0] + ty * wd, p[1] - tx * wd]);
    }
    const lens = L.concat(Rr.reverse());
    g.fillStyle = 'rgba(30,12,4,0.55)'; g.save(); g.translate(0.002, 0.004); polyPath(g, lens); g.fill(); g.restore();
    polyPath(g, lens); g.fillStyle = '#f3e4c2'; g.fill();
    /* far wall of the groove sits in shade */
    g.save(); polyPath(g, lens); g.clip();
    g.fillStyle = 'rgba(176,132,84,0.75)';
    g.beginPath(); g.moveTo(L[0][0], L[0][1]); for (let i = 1; i <= M; i++) g.lineTo(L[i][0], L[i][1]);
    for (let i = M; i >= 0; i--) g.lineTo((L[i][0] * 0.62 + lens[2 * M + 1 - i][0] * 0.38), (L[i][1] * 0.62 + lens[2 * M + 1 - i][1] * 0.38));
    g.closePath(); g.fill();
    g.restore();
  }
  /* gloss */
  g.globalCompositeOperation = 'lighter';
  blob(g, x - r * 0.36, yb - ryt * 0.60, r * 0.5, ryt * 0.32, 'rgba(255,214,170,0.30)', 'rgba(255,214,170,0)');
  blob(g, x - r * 0.42, yb - ryt * 0.68, r * 0.13, ryt * 0.07, 'rgba(255,244,224,0.75)', 'rgba(255,244,224,0)');
  g.globalCompositeOperation = 'source-over';
  g.restore();
  /* rim light on the lamp side */
  g.strokeStyle = 'rgba(255,196,140,0.42)'; g.lineWidth = 0.005; g.lineCap = 'round';
  g.beginPath(); g.ellipse(x, yb + 0.002, r - 0.002, ryt - 0.002, 0, PI * 1.05, PI * 1.55); g.stroke();
}

/* ---------- sweet corn ---------- */
function paintCorn(g, cx, cz, seed) {
  const R = rng(seed), ks = [];
  brothShadow(g, cx, cz, 0.21, 0.17, 0.55);
  for (let i = 0; i < 44; i++) {
    const a = R() * TAU, q = sqrt(R()), x = cx + cos(a) * q * 0.155, z = cz + sin(a) * q * 0.115;
    const y = 0.062 * (1 - q * q) + R() * 0.012;
    ks.push({ x, z, y, rot: (R() - 0.5) * 1.6, s: 0.9 + R() * 0.3, t: R() });
  }
  ks.sort((a, b) => (a.z + a.y * 0.4) - (b.z + b.y * 0.4));
  for (const k of ks) {
    const p = P(k.x, k.z, k.y), a = 0.021 * k.s, b = 0.0175 * k.s;
    g.save(); g.translate(p[0], p[1]); g.rotate(k.rot);
    /* kernel: a soft-cornered little tooth */
    const path = new Path2D();
    path.moveTo(-a * 0.75, -b); path.quadraticCurveTo(0, -b * 1.25, a * 0.75, -b);
    path.quadraticCurveTo(a * 1.12, -b * 0.8, a, 0); path.quadraticCurveTo(a * 0.95, b * 0.95, 0, b);
    path.quadraticCurveTo(-a * 0.95, b * 0.95, -a, 0); path.quadraticCurveTo(-a * 1.12, -b * 0.8, -a * 0.75, -b);
    g.fillStyle = 'rgba(96,40,0,0.5)'; g.save(); g.translate(0.002, 0.005); g.fill(path); g.restore();
    const gr = g.createRadialGradient(-a * 0.3, -b * 0.4, 0, 0, 0, a * 1.25);
    gr.addColorStop(0, k.t < 0.3 ? '#fff2a0' : '#ffe680'); gr.addColorStop(0.5, '#fcc63c'); gr.addColorStop(1, '#d98c14');
    g.fillStyle = gr; g.fill(path);
    g.strokeStyle = 'rgba(150,76,6,0.5)'; g.lineWidth = 0.0028; g.stroke(path);
    g.fillStyle = 'rgba(255,255,240,0.9)';
    g.beginPath(); g.ellipse(-a * 0.32, -b * 0.42, a * 0.26, b * 0.16, -0.5, 0, TAU); g.fill();
    g.restore();
  }
}

/* ---------- sliced scallion / chili: little rings with real thickness ---------- */
const RING = {
  green: ['#3f8f2c', '#a9d86a', '#27641c', '#173f10'],
  pale: ['#9cc864', '#e9f2c0', '#6f9a44', '#415f26'],
  dark: ['#27781f', '#74bb46', '#17521a', '#0c300c'],
  chili: ['#c81e14', '#f0583a', '#7e0e0a', '#4c0806'],
};
function paintRing(g, x, y, a, squash, rot, pal, R) {
  const c = RING[pal], th = a * 0.36, b = a * squash;
  g.save(); g.translate(x, y); g.rotate(rot);
  /* shadow, wall, top */
  g.fillStyle = 'rgba(40,14,0,0.42)'; g.beginPath(); g.ellipse(0.003, th + 0.006, a * 1.04, b * 1.04, 0, 0, TAU); g.fill();
  g.fillStyle = c[2]; g.beginPath(); g.ellipse(0, th, a, b, 0, 0, PI); g.rect(-a, 0, 2 * a, th); g.fill();
  const gr = g.createRadialGradient(0, 0, a * 0.45, 0, 0, a);
  gr.addColorStop(0, c[1]); gr.addColorStop(0.75, c[1]); gr.addColorStop(1, c[0]);
  g.save(); g.scale(1, squash); g.fillStyle = gr; g.beginPath(); g.arc(0, 0, a, 0, TAU); g.fill(); g.restore();
  /* the hollow: far inner wall, then the dark below */
  const hi = a * 0.56;
  g.fillStyle = c[2]; g.beginPath(); g.ellipse(0, 0, hi, hi * squash, 0, 0, TAU); g.fill();
  g.save(); g.beginPath(); g.ellipse(0, 0, hi, hi * squash, 0, 0, TAU); g.clip();
  g.fillStyle = c[3]; g.beginPath(); g.ellipse(0, th * 0.9, hi, hi * squash, 0, 0, TAU); g.fill();
  if (pal === 'chili') {
    g.fillStyle = '#f4d9a0';
    for (let i = 0; i < 3; i++) { g.beginPath(); g.ellipse((R() - 0.5) * hi, th * 0.6 + (R() - 0.5) * hi * squash, a * 0.13, a * 0.09, R() * PI, 0, TAU); g.fill(); }
  }
  g.restore();
  /* wet glint on the cut face */
  g.strokeStyle = 'rgba(255,255,240,0.62)'; g.lineWidth = a * 0.13; g.lineCap = 'round';
  g.beginPath(); g.ellipse(0, 0, a * 0.79, a * 0.79 * squash, 0, PI * 1.08, PI * 1.45); g.stroke();
  g.restore();
}

function paintScallions(g, cx, cz, seed) {
  const R = rng(seed), rs = [];
  for (let i = 0; i < 40; i++) {
    const a = R() * TAU, q = pow(R(), 0.7), x = cx + cos(a) * q * 0.19, z = cz + sin(a) * q * 0.15;
    rs.push({ x, z, y: 0.07 + 0.055 * (1 - q * q) + R() * 0.012, a: 0.022 + R() * 0.014, sq: 0.42 + R() * 0.36, rot: (R() - 0.5) * 0.9,
      pal: R() < 0.52 ? 'green' : R() < 0.55 ? 'pale' : 'dark' });
  }
  rs.sort((a, b) => (a.z + a.y) - (b.z + b.y));
  for (const r of rs) { const p = P(r.x, r.z, r.y); paintRing(g, p[0], p[1], r.a, r.sq, r.rot, r.pal, R); }
}

/* ---------- nori ---------- */
function paintNori(g, ang, rad, wid, hgt, lean, yawOff, seed) {
  const R = rng(seed);
  const bx = cos(ang) * rad, bz = sin(ang) * rad;                 // foot of the sheet, in the broth
  const tx = -sin(ang + yawOff), tz = cos(ang + yawOff);          // along the sheet
  const ox = cos(ang) * sin(lean), oz = sin(ang) * sin(lean), oy = cos(lean);   // up the sheet, leaning on the wall
  const pt = (u, v, bend) => {
    const k = (bend || 0) * sin(PI * clamp(u + 0.5, 0, 1)) * v;
    return P(bx + tx * u * wid + ox * v * hgt + cos(ang) * k, bz + tz * u * wid + oz * v * hgt + sin(ang) * k, -0.03 + oy * v * hgt);
  };
  const bend = -0.035;
  const path = new Path2D(), N = 16;
  const edge = (u0, v0, u1, v1, jag) => {
    for (let i = 0; i <= N; i++) {
      const t = i / N, p = pt(lerp(u0, u1, t), lerp(v0, v1, t), bend);
      const j = jag ? (noise2(t * 9 + seed, seed * 0.7) - 0.5) * jag : 0;
      path.lineTo(p[0] + j, p[1] + j * 0.6);
    }
  };
  const p0 = pt(-0.5, 0, bend); path.moveTo(p0[0], p0[1]);
  edge(-0.5, 0, -0.5, 1, 0.006); edge(-0.5, 1, 0.5, 1, 0.008); edge(0.5, 1, 0.5, 0, 0.006); path.closePath();
  const a = pt(-0.5, 0), b = pt(0.5, 0), c = pt(-0.5, 1), d = pt(0.5, 1);
  /* shadow cast back onto the sheet behind / the broth */
  g.fillStyle = 'rgba(0,0,0,0.35)'; g.save(); g.translate(0.012, 0.01); g.fill(path); g.restore();
  g.save(); g.clip(path);
  let gr = g.createLinearGradient(a[0], a[1], c[0], c[1]);
  gr.addColorStop(0, '#060a07'); gr.addColorStop(0.25, '#0c1710'); gr.addColorStop(0.7, '#132419'); gr.addColorStop(1, '#1b3322');
  g.fillStyle = gr; g.fill(path);
  /* pressed-seaweed texture: flecks and short fibres */
  const mnx = min(a[0], b[0], c[0], d[0]), mxx = max(a[0], b[0], c[0], d[0]), mny = min(c[1], d[1]) - 0.02, mxy = max(a[1], b[1]) + 0.02;
  for (let i = 0; i < 900; i++) {
    const x = lerp(mnx, mxx, R()), y = lerp(mny, mxy, R()), t = R();
    g.fillStyle = t < 0.55 ? rgba(70, 112, 70, 0.10 + 0.22 * R()) : t < 0.8 ? rgba(0, 0, 0, 0.3) : rgba(120, 160, 96, 0.08 + 0.14 * R());
    const s = 0.0012 + R() * R() * 0.005;
    g.beginPath(); g.ellipse(x, y, s * (1 + R() * 2.5), s, R() * PI, 0, TAU); g.fill();
  }
  /* satin sheen where the lamp grazes it */
  gr = g.createLinearGradient(c[0], c[1], lerp(b[0], d[0], 0.35), lerp(b[1], d[1], 0.35));
  gr.addColorStop(0, 'rgba(150,200,140,0.06)'); gr.addColorStop(0.3, 'rgba(160,210,150,0.24)');
  gr.addColorStop(0.52, 'rgba(120,170,120,0.05)'); gr.addColorStop(1, 'rgba(0,0,0,0)');
  g.globalCompositeOperation = 'lighter'; g.fillStyle = gr; g.fill(path); g.globalCompositeOperation = 'source-over';
  /* soaked foot */
  gr = g.createLinearGradient(a[0], a[1], lerp(a[0], c[0], 0.3), lerp(a[1], c[1], 0.3));
  gr.addColorStop(0, 'rgba(60,20,0,0.75)'); gr.addColorStop(0.6, 'rgba(20,10,0,0.3)'); gr.addColorStop(1, 'rgba(0,0,0,0)');
  g.fillStyle = gr; g.fill(path);
  g.restore();
  /* thin edge catching the light */
  g.strokeStyle = 'rgba(150,196,130,0.34)'; g.lineWidth = 0.0035; g.lineJoin = 'round';
  g.stroke(path);
  g.strokeStyle = 'rgba(214,236,170,0.5)'; g.lineWidth = 0.004;
  g.beginPath();
  for (let i = 0; i <= N; i++) { const p = pt(lerp(-0.5, 0.5, i / N), 1, bend); if (i) g.lineTo(p[0], p[1]); else g.moveTo(p[0], p[1]); }
  g.stroke();
}

/* ---------- lotus root ---------- */
function paintLotus(g, cx, cz, y, r, squash, rot, seed) {
  const R = rng(seed), c = P(cx, cz, y);
  g.save(); g.translate(c[0], c[1]); g.rotate(rot);
  const th = r * 0.14;
  g.fillStyle = 'rgba(30,8,0,0.45)'; g.beginPath(); g.ellipse(0.01, th + 0.016, r * 1.03, r * squash * 1.03, 0, 0, TAU); g.fill();
  /* cut edge */
  g.fillStyle = '#b08a52'; g.beginPath(); g.ellipse(0, th, r, r * squash, 0, 0, PI); g.rect(-r, 0, 2 * r, th); g.fill();
  let lg = g.createLinearGradient(-r, 0, r, 0);
  lg.addColorStop(0, 'rgba(60,24,4,0.5)'); lg.addColorStop(0.4, 'rgba(60,24,4,0)'); lg.addColorStop(1, 'rgba(60,24,4,0.35)');
  g.fillStyle = lg; g.beginPath(); g.ellipse(0, th, r, r * squash, 0, 0, PI); g.rect(-r, 0, 2 * r, th); g.fill();
  g.save(); g.scale(1, squash);
  /* face */
  let gr = g.createRadialGradient(-r * 0.2, -r * 0.25, 0, 0, 0, r);
  gr.addColorStop(0, '#fbf1d9'); gr.addColorStop(0.7, '#f0dfba'); gr.addColorStop(0.93, '#dcc091'); gr.addColorStop(1, '#b8915a');
  g.fillStyle = gr; g.beginPath(); g.arc(0, 0, r, 0, TAU); g.fill();
  g.save(); g.beginPath(); g.arc(0, 0, r, 0, TAU); g.clip();
  /* a little colour from the pan */
  for (let i = 0; i < 6; i++) {
    const a = R() * TAU, q = 0.3 + R() * 0.6, bx = cos(a) * r * q, by = sin(a) * r * q, br = r * (0.2 + R() * 0.3);
    const bg = g.createRadialGradient(bx, by, 0, bx, by, br);
    bg.addColorStop(0, rgba(176, 112, 40, 0.16 + 0.2 * R())); bg.addColorStop(1, 'rgba(176,112,40,0)');
    g.fillStyle = bg; g.fillRect(-r, -r, 2 * r, 2 * r);
  }
  for (let i = 0; i < 40; i++) {
    const a = R() * TAU; g.strokeStyle = rgba(150, 110, 60, 0.05 + 0.08 * R()); g.lineWidth = 0.002;
    g.beginPath(); g.moveTo(cos(a) * r * 0.2, sin(a) * r * 0.2); g.lineTo(cos(a) * r * 0.98, sin(a) * r * 0.98); g.stroke();
  }
  g.restore();
  /* holes */
  const n = 8, off = R() * TAU;
  const hole = (hx, hy, ha, hb, hr) => {
    g.save(); g.translate(hx, hy); g.rotate(hr);
    g.fillStyle = '#c9a871'; g.beginPath(); g.ellipse(0, 0, ha, hb, 0, 0, TAU); g.fill();
    g.save(); g.beginPath(); g.ellipse(0, 0, ha, hb, 0, 0, TAU); g.clip();
    g.rotate(-hr - rot);
    g.fillStyle = '#3a1606'; g.beginPath(); g.ellipse(0, th * 1.1 / squash, ha * 1.25, max(ha, hb) * 1.25, 0, 0, TAU); g.fill();
    g.restore();
    g.strokeStyle = 'rgba(120,84,40,0.55)'; g.lineWidth = 0.003; g.beginPath(); g.ellipse(0, 0, ha, hb, 0, 0, TAU); g.stroke();
    g.restore();
  };
  for (let i = 0; i < n; i++) {
    const a = off + i / n * TAU + (R() - 0.5) * 0.12, q = 0.60 + (R() - 0.5) * 0.05;
    hole(cos(a) * r * q, sin(a) * r * q, r * (0.17 + R() * 0.03), r * (0.115 + R() * 0.025), a);
  }
  hole(0, 0, r * 0.085, r * 0.085, 0);
  for (let i = 0; i < n; i++) {
    if (R() < 0.45) continue;
    const a = off + (i + 0.5) / n * TAU, q = 0.30;
    hole(cos(a) * r * q, sin(a) * r * q, r * 0.035, r * 0.035, 0);
  }
  /* skin and gloss */
  g.strokeStyle = 'rgba(150,104,54,0.9)'; g.lineWidth = 0.006; g.beginPath(); g.arc(0, 0, r - 0.003, 0, TAU); g.stroke();
  g.strokeStyle = 'rgba(255,252,236,0.6)'; g.lineWidth = 0.007; g.lineCap = 'round';
  g.beginPath(); g.arc(0, 0, r * 0.86, PI * 1.08, PI * 1.42); g.stroke();
  g.restore();
  g.restore();
}

/* ---------- baby bok choy, halved and lightly charred ---------- */
function paintBokChoy(g, bx, by, ang, len, squash, seed, flip) {
  const R = rng(seed);
  g.save(); g.translate(bx, by); g.rotate(ang); g.scale(len, len * squash * (flip ? -1 : 1));
  /* local space: stem base at u=0, leaf tips at u=1, half-width about 0.2 */
  /* shadow on the broth */
  g.fillStyle = 'rgba(40,12,0,0.40)';
  g.beginPath(); g.ellipse(0.5, 0.05, 0.56, 0.25, 0, 0, TAU); g.fill();

  const leaf = (cu, cv, ru, rv, rot, shade, sd) => {
    const LR = rng(sd), path = new Path2D(), M = 44, ph1 = LR() * TAU, ph2 = LR() * TAU;
    for (let i = 0; i <= M; i++) {
      const t = i / M * TAU;
      const k = 1 + 0.07 * sin(5 * t + ph1) + 0.045 * sin(11 * t + ph2) - 0.22 * pow(max(0, -cos(t)), 3);
      const lx = cos(t) * ru * k, ly = sin(t) * rv * k;
      const x = cu + lx * cos(rot) - ly * sin(rot), y = cv + lx * sin(rot) + ly * cos(rot);
      if (i) path.lineTo(x, y); else path.moveTo(x, y);
    }
    path.closePath();
    g.fillStyle = 'rgba(4,20,6,0.45)'; g.save(); g.translate(0.012, 0.02); g.fill(path); g.restore();
    const gr = g.createLinearGradient(cu - ru, cv - rv, cu + ru, cv + rv);
    gr.addColorStop(0, shade ? '#1c5a22' : '#2a7a2c'); gr.addColorStop(0.5, shade ? '#174a1d' : '#1f6325'); gr.addColorStop(1, shade ? '#0e3515' : '#144519');
    g.fillStyle = gr; g.fill(path);
    g.save(); g.clip(path);
    /* veins */
    const dx = cos(rot), dy = sin(rot);
    g.lineCap = 'round';
    for (let s = 0; s < 6; s++) {
      const t = -0.55 + s * 0.26, ox = cu + dx * ru * t, oy = cv + dy * ru * t;
      for (const sgn of [-1, 1]) {
        g.strokeStyle = 'rgba(150,210,110,0.42)'; g.lineWidth = 0.008;
        g.beginPath(); g.moveTo(ox, oy);
        g.quadraticCurveTo(ox + dx * ru * 0.16 - dy * rv * 0.45 * sgn, oy + dy * ru * 0.16 + dx * rv * 0.45 * sgn,
          ox + dx * ru * 0.42 - dy * rv * 1.0 * sgn, oy + dy * ru * 0.42 + dx * rv * 1.0 * sgn);
        g.stroke();
      }
    }
    /* puckered highlights between the veins */
    for (let i = 0; i < 16; i++) {
      const t = LR() * TAU, q = sqrt(LR()) * 0.8, hx = cu + cos(t) * ru * q * dx - sin(t) * rv * q * dy, hy = cv + cos(t) * ru * q * dy + sin(t) * rv * q * dx;
      const hg = g.createRadialGradient(hx, hy, 0, hx, hy, 0.06);
      hg.addColorStop(0, 'rgba(120,200,96,0.30)'); hg.addColorStop(1, 'rgba(120,200,96,0)');
      g.fillStyle = hg; g.fillRect(hx - 0.06, hy - 0.06, 0.12, 0.12);
    }
    /* midrib */
    g.strokeStyle = '#cfe6a4'; g.lineWidth = 0.03;
    g.beginPath(); g.moveTo(cu - dx * ru * 1.05, cv - dy * ru * 1.05); g.lineTo(cu + dx * ru * 0.1, cv + dy * ru * 0.1); g.stroke();
    g.lineWidth = 0.014;
    g.beginPath(); g.moveTo(cu, cv); g.lineTo(cu + dx * ru * 0.7, cv + dy * ru * 0.7); g.stroke();
    g.restore();
    g.strokeStyle = 'rgba(120,190,96,0.35)'; g.lineWidth = 0.006; g.stroke(path);
  };
  leaf(0.70, -0.105, 0.30, 0.125, -0.20, true, seed + 1);
  leaf(0.72, 0.105, 0.30, 0.125, 0.22, true, seed + 2);
  leaf(0.77, 0.0, 0.26, 0.13, 0.03, false, seed + 3);

  /* stalks: nested pale spoons, widest low down */
  const stalk = (v0, v1, bulge, tipU, tipV, c0, c1, c2) => {
    const path = new Path2D();
    path.moveTo(0.0, v0 * 0.5);
    path.bezierCurveTo(0.08, v0 * 1.2 + bulge * 0.7, 0.32, v0 + bulge, tipU, tipV + (v0 < v1 ? -0.012 : 0.012) * 0);
    path.bezierCurveTo(0.34, v1 + bulge * 0.2, 0.10, v1 * 1.1, 0.0, v1 * 0.5);
    path.closePath();
    const gr = g.createLinearGradient(0, 0, tipU, 0);
    gr.addColorStop(0, c0); gr.addColorStop(0.55, c1); gr.addColorStop(1, c2);
    g.fillStyle = 'rgba(40,70,20,0.35)'; g.save(); g.translate(0.006, 0.012); g.fill(path); g.restore();
    g.fillStyle = gr; g.fill(path);
    g.strokeStyle = 'rgba(110,150,70,0.75)'; g.lineWidth = 0.007; g.lineJoin = 'round'; g.stroke(path);
    return path;
  };
  stalk(-0.06, 0.02, -0.17, 0.60, -0.07, '#eef2d6', '#d5e7ac', '#8fbe5e');
  stalk(0.06, -0.02, 0.17, 0.60, 0.07, '#e8eecf', '#cfe3a4', '#86b656');
  stalk(-0.035, 0.035, -0.085, 0.64, -0.015, '#f6f8e6', '#e0eebd', '#a2cc70');
  stalk(0.04, -0.03, 0.08, 0.62, 0.03, '#f8faea', '#e6f1c6', '#a8d078');
  /* stem end */
  g.fillStyle = '#d9cfa0'; g.beginPath(); g.ellipse(0.012, 0, 0.03, 0.06, 0, 0, TAU); g.fill();
  g.strokeStyle = 'rgba(120,96,50,0.6)'; g.lineWidth = 0.006; g.stroke();
  /* char from the pan */
  for (let i = 0; i < 5; i++) {
    const u = 0.12 + R() * 0.4, v = (R() - 0.5) * 0.24, br = 0.04 + R() * 0.07;
    const bg = g.createRadialGradient(u, v, 0, u, v, br);
    bg.addColorStop(0, rgba(120, 70, 16, 0.20 + 0.22 * R())); bg.addColorStop(1, 'rgba(120,70,16,0)');
    g.fillStyle = bg; g.fillRect(u - br, v - br, 2 * br, 2 * br);
  }
  /* wet highlights running along the stalks */
  g.lineCap = 'round'; g.strokeStyle = 'rgba(255,255,246,0.7)';
  g.lineWidth = 0.011; g.beginPath(); g.moveTo(0.10, -0.085); g.quadraticCurveTo(0.26, -0.15, 0.44, -0.10); g.stroke();
  g.lineWidth = 0.008; g.beginPath(); g.moveTo(0.12, 0.012); g.quadraticCurveTo(0.26, -0.01, 0.42, 0.0); g.stroke();
  g.strokeStyle = 'rgba(255,255,246,0.45)';
  g.lineWidth = 0.008; g.beginPath(); g.moveTo(0.14, 0.11); g.quadraticCurveTo(0.26, 0.15, 0.38, 0.115); g.stroke();
  g.restore();
}

/* ---------- chili threads (ito togarashi) ---------- */
function paintThreads(g, cx, cz, y, seed) {
  const R = rng(seed), c = P(cx, cz, y);
  g.lineCap = 'round';
  for (let i = 0; i < 16; i++) {
    const a = R() * TAU, l = 0.05 + R() * 0.07, x0 = c[0] + (R() - 0.5) * 0.10, y0 = c[1] + (R() - 0.5) * 0.06;
    const x1 = x0 + cos(a) * l, y1 = y0 + sin(a) * l * 0.6;
    const mx = (x0 + x1) / 2 + (R() - 0.5) * 0.07, my = (y0 + y1) / 2 - 0.02 - R() * 0.04;
    g.strokeStyle = 'rgba(50,8,0,0.35)'; g.lineWidth = 0.006;
    g.beginPath(); g.moveTo(x0 + 0.002, y0 + 0.006); g.quadraticCurveTo(mx + 0.002, my + 0.008, x1 + 0.002, y1 + 0.006); g.stroke();
    g.strokeStyle = R() < 0.5 ? '#c21c10' : '#a8140c'; g.lineWidth = 0.0048;
    g.beginPath(); g.moveTo(x0, y0); g.quadraticCurveTo(mx, my, x1, y1); g.stroke();
    g.strokeStyle = 'rgba(255,150,110,0.7)'; g.lineWidth = 0.0014;
    g.beginPath(); g.moveTo(x0, y0 - 0.001); g.quadraticCurveTo(mx, my - 0.0015, x1, y1 - 0.001); g.stroke();
  }
}

/* ==========================================================================
   Plating: where everything goes. Sprites are sorted back-to-front.
   ========================================================================== */
let sprites = [];
const obstacles = [];           // footprints on the broth, so drifting oil steers around the food

function makeSprite(x0, y0, x1, y1, paint) {
  const K = view.K;
  x0 = floor(x0 * K) / K; y0 = floor(y0 * K) / K;
  const cv = mk((x1 - x0) * K + 2, (y1 - y0) * K + 2), g = cv.getContext('2d');
  g.setTransform(K, 0, 0, K, -x0 * K, -y0 * K);
  paint(g, 1 / K);
  return { cv, x: x0, y: y0, w: cv.width / K, h: cv.height / K };
}

function buildFood() {
  sprites = []; obstacles.length = 0;
  let seed = 100;
  /* item(depth z for sorting, surface anchor x/z, half-extent, painter, bob amount) */
  const item = (x, z, ext, up, paint, bob, obst) => {
    const c = P(x, z, 0);
    const sp = makeSprite(c[0] - ext, c[1] - up, c[0] + ext, c[1] + ext * 0.8, paint);
    sp.ax = c[0]; sp.ay = c[1]; sp.sx = x; sp.sz = z; sp.z = z; sp.bob = bob; sp.ph = (seed * 0.618) % 1 * TAU; sp.fr = 0.55 + ((seed * 0.371) % 1) * 0.5;
    seed += 7;
    sprites.push(sp);
    if (obst) obstacles.push([x, z, obst]);
    return sp;
  };

  /* nori: two sheets standing against the far-left wall */
  item(-0.52, -0.66, 0.5, 0.75, g => paintNori(g, -2.36, 0.80, 0.40, 0.50, 0.34, 0.06, 11), 0.15, 0.2);
  item(-0.22, -0.74, 0.5, 0.75, g => paintNori(g, -1.90, 0.80, 0.40, 0.52, 0.30, -0.05, 23), 0.15, 0.2);
  /* lotus root leaning at the back */
  item(0.20, -0.60, 0.3, 0.42, g => paintLotus(g, 0.20, -0.58, 0.10, 0.145, 0.84, -0.12, 31), 0.4, 0.16);
  item(0.42, -0.50, 0.3, 0.42, g => paintLotus(g, 0.43, -0.47, 0.075, 0.135, 0.80, 0.22, 37), 0.4, 0.15);
  /* bok choy along the left */
  { const c = P(-0.36, -0.06, 0.03); item(-0.58, -0.08, 0.6, 0.5, g => paintBokChoy(g, c[0], c[1], PI + 0.52, 0.56, 0.74, 41, false), 0.5, 0.24); }
  { const c = P(-0.30, 0.16, 0.03); item(-0.56, 0.14, 0.6, 0.5, g => paintBokChoy(g, c[0], c[1], PI + 0.16, 0.52, 0.72, 47, true), 0.5, 0.22); }
  /* noodles above the surface */
  { const sp = makeSprite(-0.9, -0.6, 0.9, 0.75, (g, px) => paintNoodles(g, px, true));
    sp.ax = 0; sp.ay = YB; sp.sx = 0; sp.sz = 0.05; sp.z = -0.02; sp.bob = 0.25; sp.ph = 1; sp.fr = 0.6; sprites.push(sp); obstacles.push([0, 0.1, 0.42]); }
  /* tofu on the right */
  item(0.50, -0.08, 0.3, 0.3, g => paintTofu(g, 0.50, -0.08, 0.42, 0.21, 0.15, 0.10, 0.0, 51), 0.8, 0.16);
  item(0.36, 0.14, 0.3, 0.3, g => paintTofu(g, 0.36, 0.14, -0.38, 0.20, 0.15, 0.10, 0.0, 57), 0.8, 0.16);
  item(0.58, 0.16, 0.3, 0.3, g => paintTofu(g, 0.59, 0.17, 1.05, 0.19, 0.14, 0.095, 0.0, 61), 0.8, 0.15);
  /* shiitake front-left */
  item(-0.47, 0.36, 0.3, 0.3, g => paintShiitake(g, -0.47, 0.36, 0.142, 0.085, 71), 0.9, 0.16);
  item(-0.22, 0.50, 0.3, 0.3, g => paintShiitake(g, -0.22, 0.50, 0.128, 0.078, 73), 0.9, 0.14);
  /* corn front-right */
  item(0.26, 0.47, 0.34, 0.3, g => paintCorn(g, 0.26, 0.47, 81), 0.6, 0.2);
  /* scallions and chili threads crowning the noodles */
  item(0.02, 0.06, 0.4, 0.42, g => { paintScallions(g, 0.02, 0.04, 91); paintThreads(g, 0.03, 0.03, 0.17, 97); }, 0.3, 0);
  sprites.sort((a, b) => a.z - b.z);
}

/* ==========================================================================
   Steam: a small fluid simulation on the CPU (semi-Lagrangian advection,
   pressure projection, buoyancy, vorticity confinement). Heat rising off
   the broth is the dye; it is painted into a tiny buffer, lit by the lamp
   and the pointer, and scaled up softly over the scene.
   ========================================================================== */
const steam = (function () {
  let NX = 0, NY = 0, KD = 2, DX = 0, DY = 0, cell = 0.04;
  let u, v, u0, v0, p, dv, cw, d, d0, rowDecay, colI, colF, maskX, maskY, lgx, lgy;
  let cv = null, cg = null, img = null;
  const reg = { x: -1.8, y: -3, w: 3.6, h: 3.7 };          // region covered, in bowl units
  let time = 0;
  const pushes = [];                                       // pending pointer impulses
  const R = rng(5150);

  /* places on the broth where heat escapes, each breathing at its own pace */
  const vents = [];
  for (const q of [[-0.30, -0.42, 1.0], [0.06, -0.36, 1.0], [0.52, -0.22, 0.8], [-0.02, -0.05, 0.75], [0.30, 0.24, 0.6], [-0.50, 0.02, 0.6], [-0.05, 0.50, 0.5], [0.62, 0.34, 0.45]]) {
    vents.push({ x: q[0], z: q[1], gain: q[2], f1: 0.11 + R() * 0.12, f2: 0.09 + R() * 0.1, p1: R() * TAU, p2: R() * TAU, seed: R() * 100, r: 0.075 + R() * 0.05 });
  }
  /* slow eddies wandering through the air above the bowl */
  const eddies = [];
  for (let i = 0; i < 5; i++) eddies.push({ x: 0, y: 0, r: 0.4, s: 0, life: 0, max: 1 });

  function resize(q) {
    const K = view.K;
    cell = q <= 0 ? 0.056 : q === 1 ? 0.042 : 0.034;
    KD = 2;
    const left = max(-1.85, -view.ox / K - 0.15), right = min(1.85, (canvas.width - view.ox) / K + 0.15);
    const top = max(-3.9, -view.oy / K - 0.2), bottom = 0.74;
    const nx = max(24, round((right - left) / cell)), ny = max(24, round((bottom - top) / cell));
    reg.x = left; reg.y = top; reg.w = nx * cell; reg.h = ny * cell;
    const keep = (nx === NX && ny === NY);
    NX = nx; NY = ny; DX = NX * KD; DY = NY * KD;
    if (!keep) {
      const n = NX * NY, m = DX * DY;
      u = new Float32Array(n); v = new Float32Array(n); u0 = new Float32Array(n); v0 = new Float32Array(n);
      p = new Float32Array(n); dv = new Float32Array(n); cw = new Float32Array(n);
      d = new Float32Array(m); d0 = new Float32Array(m);
      rowDecay = new Float32Array(DY); colI = new Int32Array(DX); colF = new Float32Array(DX);
