      const y = reg.y + (J + 0.5) * cell / KD, t = (J + 0.5) / DY;
      /* thin over the food so the dish stays crisp, full above the rim, gone before the top edge */
      maskY[J] = sstep(0, 0.14, t) * (0.34 + 0.66 * sstep(0.30, -0.78, y)) * sstep(0.74, 0.5, y);
