  function splatVel(x, y, ax, ay, rad) {                  // bowl units
    const gx = (x - reg.x) / cell - 0.5, gy = (y - reg.y) / cell - 0.5, rr = rad / cell;
    const i0 = max(1, floor(gx - rr * 2.2)), i1 = min(NX - 2, ceil(gx + rr * 2.2));
