    const i0 = max(1, floor(gx - rr * 2.2)), i1 = min(DX - 2, ceil(gx + rr * 2.2));
    const j0 = max(1, floor(gy - rr * 2.2)), j1 = min(DY - 2, ceil(gy + rr * 2.2)), inv = 1 / (rr * rr);
