/* ==========================================================================
   The living parts: light that follows the pointer, the broth surface,
   ripples, drifting oil and garnish, dust in the lamplight.
   ========================================================================== */
let reduced = false;

const pointer = { x: 0, y: 0, vx: 0, vy: 0, has: false, t: -1e9, trail: 0 };
const light = { x: -0.62, y: -1.22, dx: -0.4, dy: -0.9, k: 0.6, sx: 0, sz: 0, a: 0, presence: 0, power: 1, front: 0 };

function updateLight(dt, t) {
  const ix = -0.62 + 0.12 * sin(t * 0.21), iy = -1.22 + 0.08 * sin(t * 0.17 + 2.0);
  const tx = pointer.has ? pointer.x : ix, ty = pointer.has ? pointer.y : iy;
  const rate = 1 - exp(-dt * (pointer.has ? 7 : 1.3));
  light.x += (tx - light.x) * rate; light.y += (ty - light.y) * rate;
  light.presence += ((pointer.has ? 1 : 0) - light.presence) * (1 - exp(-dt * 3));
  /* a lamp is never perfectly steady */
  light.power = reduced ? 1 : 1 + 0.035 * sin(t * 7.3) * sin(t * 2.9 + 1.1) + 0.05 * (noise2(t * 1.7, 9.1) - 0.5);
  deriveLight();
}
function deriveLight() {
  const ex = light.x, ey = light.y - YB * 0.5, m = hypot(ex, ey) + 1e-6, k = m / (m + 0.9);
  light.dx = ex / m; light.dy = ey / m; light.k = k;
  light.sx = light.dx * k * 0.74; light.sz = light.dy * k * 0.74;       // where the broth mirrors the lamp
  light.a = atan2(light.dy, light.dx);                                   // where the lip catches it
  light.front = sstep(-0.7, 0.9, light.y);
}

/* ---------- ripples ---------- */
const ripples = [];
function addRipple(x, z, amp) {
  if (ripples.length >= 26) ripples.shift();
  ripples.push({ x, z, t: 0, amp, rad: 0.02, fade: amp });
}
function onBroth(x, y) {                  // bowl-unit screen point → is it over open broth?
  const z = (y - YB) / SQ;
  if (x * x + z * z > RB * RB * 0.93) return false;
  const e = RIM_IN * 0.985;
  return (x * x) / (e * e) + (y * y) / (e * e * SQ * SQ) < 1;
}

/* ---------- things adrift on the broth ---------- */
const floaters = [];
let dropSprite = null, ringSprites = [];
function isOpen(x, z, m) {
  if (hypot(x, z) > 0.86) return false;
  for (const o of obstacles) if (hypot(x - o[0], z - o[1]) < o[2] + m) return false;
  return true;
}
function initFloaters() {
  const R = rng(8088);
  floaters.length = 0;
  const place = (m) => {
    for (let i = 0; i < 80; i++) {
      const a = R() * TAU, q = sqrt(R()) * 0.86, x = cos(a) * q, z = sin(a) * q * 0.98;
      if (z < 0.74 && isOpen(x, z, m)) return [x, z];
    }
    const a = R() * TAU; return [cos(a) * 0.8, sin(a) * 0.72];
  };
  const add = (type, n, s0, s1, m) => {
    for (let i = 0; i < n; i++) {
      const p = place(m);
      floaters.push({ type, x: p[0], z: p[1], vx: 0, vz: 0, s: lerp(s0, s1, R() * R()), rot: R() * TAU, spin: (R() - 0.5) * 0.3, ph: R() * TAU, v: R() });
    }
  };
  add(0, 46, 0.010, 0.040, 0.01);       // chili-oil droplets
  add(1, 18, 1, 1, 0.01);               // sesame
  add(2, 8, 0.024, 0.032, 0.03);        // stray scallion rings
  add(3, 16, 0.004, 0.009, 0.0);        // chili flakes
  floaters.sort((a, b) => a.type - b.type || a.z - b.z);
}
function buildFloaterSprites() {
  dropSprite = mk(64, 64);
  let g = dropSprite.getContext('2d'), gr = g.createRadialGradient(32, 32, 0, 32, 32, 31);
  gr.addColorStop(0, 'rgba(255,204,104,0.26)'); gr.addColorStop(0.55, 'rgba(250,156,52,0.38)');
  gr.addColorStop(0.86, 'rgba(228,86,24,0.62)'); gr.addColorStop(0.95, 'rgba(176,46,10,0.70)'); gr.addColorStop(1, 'rgba(176,46,10,0)');
  g.fillStyle = gr; g.beginPath(); g.arc(32, 32, 31.5, 0, TAU); g.fill();
  ringSprites = [];
  const R = rng(31337);
  for (const pal of ['green', 'pale', 'dark']) {
    ringSprites.push(makeSprite(-0.06, -0.05, 0.06, 0.06, gg => paintRing(gg, 0, 0, 0.03, 0.6, 0, pal, R)));
  }
}
function updateFloaters(dt, t) {
  const pOn = pointer.has && onBroth(pointer.x, pointer.y), pxs = pointer.x, pzs = (pointer.y - YB) / SQ;
  for (const f of floaters) {
    /* slow convection: a divergence-free stream function that changes with time */
    const x = f.x, z = f.z;
    let fx = 0.030 * (-2.9 * sin(2.3 * x + 0.21 * t) * sin(2.9 * z - 0.17 * t) + 2.5 * cos(4.1 * z + 0.13 * t + 1.3) * cos(3.3 * x + 0.4));
    let fz = -0.030 * (2.3 * cos(2.3 * x + 0.21 * t) * cos(2.9 * z - 0.17 * t) - 2.0 * sin(4.1 * z + 0.13 * t + 1.3) * sin(3.3 * x + 0.4));
    fx *= 0.5; fz *= 0.5;
    f.vx += (fx - f.vx) * min(1, dt * 1.6); f.vz += (fz - f.vz) * min(1, dt * 1.6);
    for (const o of obstacles) {
      const ox = x - o[0], oz = z - o[1], dd = hypot(ox, oz) + 1e-6, lim = o[2] + f.s * (f.type === 0 ? 1 : 0.5) + 0.012;
      if (dd < lim) { const q = (lim - dd) / dd; f.vx += ox * q * 9 * dt; f.vz += oz * q * 9 * dt; }
    }
    const rr = hypot(x, z);
    if (rr > 0.84) { const q = (rr - 0.84) / rr; f.vx -= x * q * 10 * dt; f.vz -= z * q * 10 * dt; }
    if (pOn) {
      const ox = x - pxs, oz = z - pzs, dd2 = ox * ox + oz * oz, w = exp(-dd2 / 0.03);
      f.vx += (pointer.vx * 0.5 + ox * 2.5) * w * dt; f.vz += (pointer.vy / SQ * 0.5 + oz * 2.5) * w * dt;
    }
    for (const r of ripples) {
      const ox = x - r.x, oz = z - r.z, dd = hypot(ox, oz) + 1e-6, e = dd - r.rad;
      if (e > -0.09 && e < 0.09) { const w = r.fade * 0.42 * (1 - abs(e) / 0.09) * dt / dd; f.vx += ox * w; f.vz += oz * w; }
    }
    const sp = hypot(f.vx, f.vz); if (sp > 0.5) { f.vx *= 0.5 / sp; f.vz *= 0.5 / sp; }
    f.x += f.vx * dt; f.z += f.vz * dt;
    f.rot += f.spin * dt + (f.vx - f.vz) * dt * 2;
  }
  for (let i = ripples.length - 1; i >= 0; i--) {
    const r = ripples[i]; r.t += dt; r.rad = 0.02 + 0.40 * r.t; r.fade = r.amp * pow(max(0, 1 - r.t / 2.6), 2);
    if (r.t > 2.6) ripples.splice(i, 1);
  }
}

/* glints: the lamp broken up by the trembling surface */
const glints = [];
(function () { const R = rng(606); for (let i = 0; i < 26; i++) glints.push({ x: (R() - 0.5) * 1.6, z: (R() - 0.5) * 1.5, w: 0.025 + R() * 0.06, f: 0.5 + R() * 1.4, ph: R() * TAU, v: R() }); })();

function drawBroth(g, t) {
  g.save(); clipBroth(g);
  const pw = light.power, c = P(light.sx, light.sz, 0);
  /* the lamp mirrored in the broth */
  g.globalCompositeOperation = 'lighter';
  blob(g, c[0], c[1], 0.62, 0.62 * SQ, rgba(255, 214, 150, 0.21 * pw), 'rgba(255,200,130,0)', [0.45, rgba(255, 200, 130, 0.07 * pw)]);
  blob(g, c[0], c[1], 0.22, 0.22 * SQ, rgba(255, 240, 210, 0.20 * pw), 'rgba(255,236,200,0)');
  /* shimmer */
  for (const q of glints) {
    const x = q.x + 0.05 * sin(t * 0.21 * q.f + q.ph), z = q.z + 0.04 * cos(t * 0.17 * q.f + q.ph * 1.3);
    const ddx = x - light.sx, ddz = z - light.sz, near = exp(-(ddx * ddx + ddz * ddz) / 0.20);
    const fl = reduced ? 0.5 : pow(0.5 + 0.5 * sin(t * q.f * 1.9 + q.ph), 3);
