87	    const x = f.x, z = f.z;
88	    let fx = 0.030 * (-2.9 * sin(2.3 * x + 0.21 * t) * sin(2.9 * z - 0.17 * t) + 2.5 * cos(4.1 * z + 0.13 * t + 1.3) * cos(3.3 * x + 0.4));
89	    let fz = -0.030 * (2.3 * cos(2.3 * x + 0.21 * t) * cos(2.9 * z - 0.17 * t) - 2.0 * sin(4.1 * z + 0.13 * t + 1.3) * sin(3.3 * x + 0.4));
90	    fx *= 0.5; fz *= 0.5;
91	    f.vx += (fx - f.vx) * min(1, dt * 1.6); f.vz += (fz - f.vz) * min(1, dt * 1.6);
92	    for (const o of obstacles) {
