s = s.replace('function step(dt) {', 'function step(dt) { window.__tk(-1);');
s = s.replace("(function () {\n'use strict';", "(function () {\n'use strict';\nwindow.__T = new Float64Array(9); let __last = 0, __ph = -1; window.__tk = (i) => { const t = performance.now(); if (__ph >= 0) window.__T[__ph] += t - __last; __last = t; __ph = i + 1; };");
fs.writeFileSync('<TMP>/shots/debug_prof.html', s);
(async () => {
