    __dbg.steam.warm(300, 1 / 60, 1e9);                 // get hot
    __T.fill(0);
    const N = 600, t0 = performance.now();
    __dbg.steam.warm(N, 1 / 60, 1e9); __tk(-2);
    const tot = (performance.now() - t0) / N;
