  });
  console.log('total ms/step', r.tot.toFixed(3));
  r.T.forEach((v, i) => { if (names[i]) console.log(names[i].padEnd(16), v.toFixed(3)); });
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });
